-- TimesOps Partner & Commission v1.0.0 — ADD ONLY
SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS partner_commission_settings (id TINYINT UNSIGNED PRIMARY KEY,default_rate DECIMAL(7,4) NOT NULL DEFAULT 15.0000,default_mode ENUM('lifetime','12_months','24_months','one_time') NOT NULL DEFAULT 'lifetime',referral_window_days INT UNSIGNED NOT NULL DEFAULT 30,created_at DATETIME NULL,updated_at DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO partner_commission_settings VALUES(1,15.0000,'lifetime',30,NOW(),NOW());
CREATE TABLE IF NOT EXISTS partner_commission_partners (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(190) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(80) NULL,referral_code VARCHAR(40) NOT NULL,commission_rate DECIMAL(7,4) NOT NULL DEFAULT 15.0000,commission_mode ENUM('lifetime','12_months','24_months','one_time') NOT NULL DEFAULT 'lifetime',password_hash VARCHAR(255) NOT NULL,payout_method VARCHAR(80) NULL,payout_details VARCHAR(1000) NULL,status ENUM('active','suspended','closed') NOT NULL DEFAULT 'active',created_at DATETIME NULL,updated_at DATETIME NULL,UNIQUE KEY uq_pc_partner_email(email),UNIQUE KEY uq_pc_partner_code(referral_code),KEY idx_pc_partner_status(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS partner_commission_assignments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,partner_id BIGINT UNSIGNED NOT NULL,company_id BIGINT UNSIGNED NOT NULL,commission_rate_override DECIMAL(7,4) NULL,starts_at DATETIME NOT NULL,ends_at DATETIME NULL,status ENUM('active','ended') NOT NULL DEFAULT 'active',attribution_source ENUM('owner_assignment','referral_link','import') NOT NULL DEFAULT 'owner_assignment',referral_code VARCHAR(40) NULL,notes VARCHAR(1000) NULL,assigned_by BIGINT UNSIGNED NULL,created_at DATETIME NULL,updated_at DATETIME NULL,KEY idx_pc_assign_partner(partner_id,status),KEY idx_pc_assign_company(company_id,status),KEY idx_pc_assign_window(company_id,starts_at,ends_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS partner_commission_payment_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,settlement_key VARCHAR(220) NOT NULL,company_id BIGINT UNSIGNED NOT NULL,gross_amount DECIMAL(18,2) NOT NULL DEFAULT 0,commissionable_amount DECIMAL(18,2) NOT NULL DEFAULT 0,currency VARCHAR(10) NOT NULL,gateway VARCHAR(50) NULL,provider_reference VARCHAR(190) NULL,status ENUM('settled','reversed') NOT NULL DEFAULT 'settled',paid_at DATETIME NOT NULL,metadata_json LONGTEXT NULL,created_at DATETIME NULL,updated_at DATETIME NULL,UNIQUE KEY uq_pc_settlement_key(settlement_key),KEY idx_pc_event_company(company_id,paid_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS partner_commission_payouts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,partner_id BIGINT UNSIGNED NOT NULL,payout_reference VARCHAR(120) NOT NULL,currency VARCHAR(10) NOT NULL,amount DECIMAL(18,2) NOT NULL DEFAULT 0,status ENUM('paid','cancelled') NOT NULL DEFAULT 'paid',payment_method VARCHAR(80) NOT NULL,payment_reference VARCHAR(190) NULL,notes VARCHAR(1000) NULL,created_by BIGINT UNSIGNED NULL,paid_at DATETIME NULL,created_at DATETIME NULL,updated_at DATETIME NULL,UNIQUE KEY uq_pc_payout_ref(payout_reference),KEY idx_pc_payout_partner(partner_id,paid_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS partner_commission_ledger (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,partner_id BIGINT UNSIGNED NOT NULL,company_id BIGINT UNSIGNED NOT NULL,assignment_id BIGINT UNSIGNED NOT NULL,payment_event_id BIGINT UNSIGNED NOT NULL,rate DECIMAL(7,4) NOT NULL,commission_amount DECIMAL(18,2) NOT NULL,currency VARCHAR(10) NOT NULL,status ENUM('pending','approved','paid','reversed') NOT NULL DEFAULT 'pending',earned_at DATETIME NOT NULL,approved_by BIGINT UNSIGNED NULL,approved_at DATETIME NULL,payout_id BIGINT UNSIGNED NULL,paid_at DATETIME NULL,reversal_amount DECIMAL(18,2) NULL,reversal_reason VARCHAR(500) NULL,reversed_at DATETIME NULL,created_at DATETIME NULL,updated_at DATETIME NULL,UNIQUE KEY uq_pc_ledger_payment(payment_event_id),KEY idx_pc_ledger_partner(partner_id,status,currency),KEY idx_pc_ledger_company(company_id,earned_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS partner_commission_payout_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,payout_id BIGINT UNSIGNED NOT NULL,commission_id BIGINT UNSIGNED NOT NULL,amount DECIMAL(18,2) NOT NULL,created_at DATETIME NULL,UNIQUE KEY uq_pc_payout_commission(commission_id),KEY idx_pc_payout_items(payout_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS partner_commission_audit (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,action VARCHAR(80) NOT NULL,entity VARCHAR(80) NOT NULL,entity_id BIGINT UNSIGNED NULL,summary VARCHAR(500) NULL,metadata_json LONGTEXT NULL,created_at DATETIME NOT NULL,KEY idx_pc_audit_entity(entity,entity_id),KEY idx_pc_audit_created(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;